import Cell from "./Cell.svelte";
import { parts } from "./parts";
import Velocity from "./Velocity.svelte";

export const Sequencer = { Cell, Root: parts.Root, Row: parts.Row, Velocity };

import { sequencer } from "@audio-ui/primitives/sequencer";
import { createParts } from "@ui-sdk/svelte/primitive";

/** Which element each part is. */
export const parts = createParts(sequencer, {
  cell: "button",
  root: "div",
  row: "div",
  velocity: "div",
  velocityInput: "input",
});

/** The props a part names, without the open index signature that would turn them into `unknown` under `Omit`. */
export type Known<T> = {
  [K in keyof T as string extends K
    ? never
    : number extends K
      ? never
      : symbol extends K
        ? never
        : K]: T[K];
};
